module mad_calculator (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] h, w,\n    input [3:0] a, b,\n    input [63:0] grid,\n    output reg [31:0] median,\n    output reg done\n);\n\nlocalparam [1:0] S_IDLE               = 2'd0;\nlocalparam [1:0] S_COMPUTE_PS         = 2'd1;\nlocalparam [1:0] S_INIT_RECT          = 2'd2;\nlocalparam [1:0] S_CHECK_RECT         = 2'd3;\nlocalparam [1:0] S_COMPUTE_RECT       = 3'd4;\nlocalparam [1:0] S_STORE_RECT         = 3'd5;\nlocalparam [1:0] S_NEXT_ITER          = 3'd6;\nlocalparam [1:0] S_SORT_INIT          = 3'd7;\nlocalparam [1:0] S_SORT_INNER_LOOP    = 4'd8;\nlocalparam [1:0] S_SORT_COMPARE       = 4'd9;\nlocalparam [1:0] S_SORT_SWAP          = 4'd10;\nlocalparam [1:0] S_SORT_INCREMENT_J   = 4'd11;\nlocalparam [1:0] S_MEDIAN             = 4'd13;\nlocalparam [1:0] S_COMPUTE_DENSITY    = 4'd14;\nlocalparam [1:0] S_DONE               = 4'd15;\n\nreg [3:0] state;\nreg [7:0] grid_2d [0:3][0:1];\nreg [31:0] ps [0:4][0:2];\nreg [3:0] top, bottom, left, right;\nreg [5:0] rect_count;\nreg [31:0] rect_sum [0:29];\nreg [3:0] rect_area [0:29];\nreg [5:0] sort_i, sort_j;\nreg [31:0] temp_sum;\nreg [3:0] temp_area;\nreg [31:0] median_temp, divisor_temp;\nreg [63:0] product1, product2;\ninteger i, j;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        median <= 32'd0;\n        rect_count <= 6'd0;\n\n        for (i = 0; i < 4; i = i + 1) begin\n            for (j = 0; j < 2; j = j + 1) begin\n                grid_2d[i][j] <= 8'd0;\n            end\n        end\n\n        for (i = 0; i <= 4; i = i + 1) begin\n            for (j = 0; j <= 2; j = j + 1) begin\n                ps[i][j] <= 32'd0;\n            end\n        end\n\n        for (i = 0; i < 30; i = i + 1) begin\n            rect_sum[i] <= 32'd0;\n            rect_area[i] <= 4'd0;\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    grid_2d[0][0] <= grid[7:0];\n                    grid_2d[0][1] <= grid[15:8];\n                    grid_2d[1][0] <= grid[23:16];\n                    grid_2d[1][1] <= grid[31:24];\n                    grid_2d[2][0] <= grid[39:32];\n                    grid_2d[2][1] <= grid[47:40];\n                    grid_2d[3][0] <= grid[55:48];\n                    grid_2d[3][1] <= grid[63:56];\n                    state <= S_COMPUTE_PS;\n                    i <= 0;\n                    j <= 0;\n                end\n            end\n\n            S_COMPUTE_PS: begin\n                if (i <= h && j <= w) begin\n                    if (i == 4'd0 || j == 4'd0) begin\n                        ps[i][j] <= 32'd0;\n                    end else begin\n                        ps[i][j] <= ps[i-1][j] + ps[i][j-1] - ps[i-1][j-1] + grid_2d[i-1][j-1];\n                    end\n\n                    if (j < w) begin\n                        j <= j + 4'd1;\n                    end else begin\n                        j <= 4'd0;\n                        if (i < h) begin\n                            i <= i + 4'd1;\n                        end else begin\n                            state <= S_INIT_RECT;\n                        end\n                    end\n                end else begin\n                    state <= S_INIT_RECT;\n                end\n            end\n\n            S_INIT_RECT: begin\n                top <= 4'd0;\n                bottom <= 4'd0;\n                left <= 4'd0;\n                right <= 4'd0;\n                rect_count <= 6'd0;\n                state <= S_CHECK_RECT;\n            end\n\n            S_CHECK_RECT: begin\n                if (bottom < h && right < w) begin\n                    state <= S_COMPUTE_RECT;\n                end else begin\n                    state <= S_NEXT_ITER;\n                end\n            end\n\n            S_COMPUTE_RECT: begin\n                temp_area <= (bottom - top + 4'd1) * (right - left + 4'd1);\n                temp_sum <= ps[bottom+1][right+1] - ps[top][right+1] - ps[bottom+1][left] + ps[top][left];\n                state <= S_STORE_RECT;\n            end\n\n            S_STORE_RECT: begin\n                if (temp_area >= a && temp_area <= b && rect_count < 6'd30) begin\n                    rect_sum[rect_count] <= temp_sum;\n                    rect_area[rect_count] <= temp_area;\n                    rect_count <= rect_count + 6'd1;\n                end\n                state <= S_NEXT_ITER;\n            end\n\n            S_NEXT_ITER: begin\n                if (right < (w - 4'd1)) begin\n                    right <= right + 4'd1;\n                end else if (left < (w - 4'd1)) begin\n                    left <= left + 4'd1;\n                    right <= left;\n                end else if (bottom < (h - 4'd1)) begin\n                    bottom <= bottom + 4'd1;\n                    left <= 4'd0;\n                    right <= 4'd0;\n                end else if (top < (h - 4'd1)) begin\n                    top <= top + 4'd1;\n                    bottom <= top;\n                    left <= 4'd0;\n                    right <= 4'd0;\n                end else begin\n                    if (rect_count == 6'd0) begin\n                        median <= 32'd0;\n                        state <= S_DONE;\n                    end else begin\n                        state <= S_SORT_INIT;\n                    end\n                    sort_i <= 6'd0;\n                    sort_j <= 6'd0;\n                    i <= 0;\n                    j <= 0;\n                    return;\n                end\n                state <= S_CHECK_RECT;\n            end\n\n            S_SORT_INIT: begin\n                sort_i <= 6'd0;\n                state <= S_SORT_INNER_LOOP;\n            end\n\n            S_SORT_INNER_LOOP: begin\n                if (sort_i < rect_count - 6'd1) begin\n                    sort_j <= 6'd0;\n                    state <= S_SORT_COMPARE;\n                end else begin\n                    state <= S_MEDIAN;\n                end\n            end\n\n            S_SORT_COMPARE: begin\n                product1 <= rect_sum[sort_j] * rect_area[sort_j+6'd1];\n                product2 <= rect_sum[sort_j+6'd1] * rect_area[sort_j];\n                state <= S_SORT_SWAP;\n            end\n\n            S_SORT_SWAP: begin\n                if (product1 > product2) begin\n                    rect_sum[sort_j] <= rect_sum[sort_j+6'd1];\n                    rect_sum[sort_j+6'd1] <= rect_sum[sort_j];\n                    rect_area[sort_j] <= rect_area[sort_j+6'd1];\n                    rect_area[sort_j+6'd1] <= rect_area[sort_j];\n                end\n                state <= S_SORT_INCREMENT_J;\n            end\n\n            S_SORT_INCREMENT_J: begin\n                if (sort_j < rect_count - sort_i - 6'd1) begin\n                    sort_j <= sort_j + 6'd1;\n                    state <= S_SORT_COMPARE;\n                end else begin\n                    sort_i <= sort_i + 6'd1;\n                    state <= S_SORT_INNER_LOOP;\n                end\n            end\n\n            S_MEDIAN: begin\n                if (rect_count[0] == 1'b1) begin\n                    median_temp <= rect_sum[rect_count >> 4'd1];\n                    divisor_temp <= rect_area[rect_count >> 4'd1];\n                end else begin\n                    median_temp <= rect_sum[(rect_count >> 4'd1) - 6'd1] + rect_sum[rect_count >> 4'd1];\n                    divisor_temp <= rect_area[(rect_count >> 4'd1) - 6'd1] + rect_area[rect_count >> 4'd1];\n                end\n                state <= S_COMPUTE_DENSITY;\n            end\n\n            S_COMPUTE_DENSITY: begin\n                if (divisor_temp != 32'd0) begin\n                    median <= (median_temp << 5'd16) / divisor_temp;\n                end else begin\n                    median <= 32'd0;\n                end\n                state <= S_DONE;\n            end\n\n            S_DONE: begin\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n\n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule